/* global CustomFunctions, AbortController */

import { arborAxiosLimiter } from "../http/limiter";
import {
  ArborDeepFailResult,
  ArborDeepResult,
  ArborDeepSuccessResult,
  ArborFastSuccessResult,
  ArborNumberFailResult,
  ArborNumberSuccessResult,
} from "./types";
import { arborDeep } from "./arborDeep";
import { arborFast } from "./arborFast";
import { cellProvider, successCellIcon } from "../constants";
import { returnErrorEntity } from "./utils";
import { AxiosError } from "axios";
import { isVersionSupported } from "./utils";

async function numberExtractRequest(ticker: string, query: string, context: string, controller: AbortController) {
  return arborAxiosLimiter.post(
    "/api/v1/screener/numeric-extract",
    {
      query: query,
      context: context,
      stockSymbol: ticker,
    },
    {
      signal: controller.signal,
      // @ts-ignore
      controller,
    }
  );
}
/**
 * Answers questions about a company based on its stock symbol in a short format.
 * @customfunction ARBOR_NUMBER
 * @param {string} ticker The stock symbol of the company
 * @param {string} query The question to ask about the company
 * @param {string} [knowledgeSpace] The knowledge space to use options: 'internet', 'private', 'hybrid', default is 'internet'
 * @param {string[][]} [privateFileFiltering] The private file filtering to use, format: [["id:123", "label1"], ["id:456", "label2"]]
 * @param {CustomFunctions.CancelableInvocation} invocation Invocation object.
 * @returns {Promise<Excel.EntityCellValue | string>} The answer to the query
 * @cancellable
 * @helpurl https://docs.arborchat.ai/arborchat-for-excel/available-functions
 */
export async function answerNumber(
  ticker: string,
  query: string,
  knowledgeSpace: string,
  privateFileFiltering: string[][],
  invocation: CustomFunctions.CancelableInvocation
): Promise<Excel.EntityCellValue | string> {
  // backward compatibility
  if (knowledgeSpace && knowledgeSpace["functionName"]) {
    invocation = knowledgeSpace as unknown as CustomFunctions.CancelableInvocation;
    knowledgeSpace = undefined;
    privateFileFiltering = undefined;
  }

  if (privateFileFiltering && privateFileFiltering["functionName"]) {
    invocation = privateFileFiltering as unknown as CustomFunctions.CancelableInvocation;
    privateFileFiltering = undefined;
  }
  const diagnostic = Office.context.diagnostics;
  const isSupported = isVersionSupported(
    diagnostic.host as unknown as string,
    diagnostic.platform as unknown as string,
    diagnostic.version as unknown as string
  );
  if (!query.trim()) {
    throw new CustomFunctions.Error(CustomFunctions.ErrorCode.invalidValue, "Query is required");
  }
  if (!ticker.trim()) {
    throw new CustomFunctions.Error(CustomFunctions.ErrorCode.invalidValue, "Ticker is required");
  }
  if (knowledgeSpace && !["internet", "hybrid", "private"].includes(knowledgeSpace)) {
    throw new CustomFunctions.Error(
      CustomFunctions.ErrorCode.invalidValue,
      "Knowledge space is invalid, options: 'internet', 'hybrid', 'private'"
    );
  }
  let fileIds: string[] = [];
  let labels: string[] = [];
  (privateFileFiltering || []).forEach((array) => {
    array.forEach((str) => {
      if (str.startsWith("id:")) {
        fileIds.push(str.split(":")[1]);
      } else {
        labels.push(str);
      }
    });
  });

  let queryType: "ARBOR_FAST" | "ARBOR_DEEP" = "ARBOR_FAST";
  try {
    const fastAnswer = await arborFast(ticker, query, false, knowledgeSpace, privateFileFiltering, invocation).catch(
      () => null
    );
    if (fastAnswer && fastAnswer?.properties?.answer?.basicValue) {
      const context = fastAnswer.properties.answer.basicValue;
      const controller = new AbortController();
      invocation.onCanceled = () => {
        controller.abort();
      };
      const numberAnswerResponse = await numberExtractRequest(ticker, query, context, controller);
      if (!numberAnswerResponse.data?.result) {
        const errorEntity = returnErrorEntity<ArborNumberFailResult>(
          new AxiosError(
            "FailToAnswer",
            numberAnswerResponse.status.toString(),
            numberAnswerResponse.config,
            numberAnswerResponse.request
          ),
          {
            type: {
              type: Excel.CellValueType.string,
              basicValue: "ARBOR_NUMBER",
            },
            queryType: {
              type: Excel.CellValueType.string,
              basicValue: queryType,
            },
            query: {
              type: Excel.CellValueType.string,
              basicValue: query,
            },
            ticker: {
              type: Excel.CellValueType.string,
              basicValue: ticker,
            },
            reason: {
              type: Excel.CellValueType.string,
              basicValue: context,
            },
            knowledgeSpace: {
              type: Excel.CellValueType.string,
              basicValue: knowledgeSpace || "internet",
            },
            ...(numberAnswerResponse.data?.properties?.queriedAt?.basicValue && {
              queriedAt: {
                type: Excel.CellValueType.string,
                basicValue: numberAnswerResponse.data.properties.queriedAt?.basicValue || "",
              },
            }),
            ...(fastAnswer.properties?.privateFileFiltering?.elements && {
              privateFileFiltering: {
                type: Excel.CellValueType.array,
                elements: fastAnswer.properties.privateFileFiltering.elements,
              },
            }),
          }
        );
        console.log("ARBOR_NUMBER", ticker, query, errorEntity);
        if (!isSupported) {
          return errorEntity.text;
        }
        return errorEntity;
      }
      const numberAnswer = numberAnswerResponse.data.result;
      const entity: ArborNumberSuccessResult = {
        type: Excel.CellValueType.entity,
        text: `${numberAnswer.answer}`,
        provider: cellProvider,
        properties: {
          ...(fastAnswer as ArborFastSuccessResult).properties,
          type: {
            type: Excel.CellValueType.string,
            basicValue: "ARBOR_NUMBER",
          },
          queryType: {
            type: Excel.CellValueType.string,
            basicValue: queryType,
          },
          answer: {
            type: Excel.CellValueType.double,
            basicValue: numberAnswer.answer,
          },
          reason: {
            type: Excel.CellValueType.string,
            basicValue: context,
          },
          knowledgeSpace: {
            type: Excel.CellValueType.string,
            basicValue: knowledgeSpace || "internet",
          },
        },
        layouts: {
          compact: {
            icon: successCellIcon,
          },
        },
      };
      console.log("ARBOR_NUMBER", ticker, query, entity);
      if (!isSupported) {
        return entity.text;
      }
      return entity;
    }

    queryType = "ARBOR_DEEP";
    const deepResponse: ArborDeepResult = (await arborDeep(
      ticker,
      query,
      false,
      knowledgeSpace,
      privateFileFiltering,
      invocation
    )) as ArborDeepResult;
    if (!deepResponse.properties.success.basicValue) {
      const data = deepResponse as ArborDeepFailResult;
      const errorEntity = returnErrorEntity<ArborNumberFailResult>(new Error(data.properties.error.basicValue), {
        type: {
          type: Excel.CellValueType.string,
          basicValue: "ARBOR_NUMBER",
        },
        queryType: {
          type: Excel.CellValueType.string,
          basicValue: queryType,
        },
        query: {
          type: Excel.CellValueType.string,
          basicValue: query,
        },
        ticker: {
          type: Excel.CellValueType.string,
          basicValue: ticker,
        },
        knowledgeSpace: {
          type: Excel.CellValueType.string,
          basicValue: knowledgeSpace || "internet",
        },
        ...(data.properties?.queriedAt?.basicValue && {
          queriedAt: {
            type: Excel.CellValueType.string,
            basicValue: data.properties.queriedAt?.basicValue || "",
          },
        }),
        ...(deepResponse.properties?.privateFileFiltering?.elements && {
          privateFileFiltering: {
            type: Excel.CellValueType.array,
            elements: deepResponse.properties.privateFileFiltering.elements,
          },
        }),
      });
      console.log("ARBOR_NUMBER", ticker, query, errorEntity);
      if (!isSupported) {
        return errorEntity.text;
      }
      return errorEntity;
    }

    const context = (deepResponse as ArborDeepSuccessResult).properties.answer.basicValue;
    const controller = new AbortController();
    invocation.onCanceled = () => {
      controller.abort();
    };
    const numberAnswerResponse = await numberExtractRequest(ticker, query, context, controller);
    if (!numberAnswerResponse.data?.result) {
      const errorEntity = returnErrorEntity<ArborNumberFailResult>(
        new AxiosError(
          "FailToAnswer",
          numberAnswerResponse.status.toString(),
          numberAnswerResponse.config,
          numberAnswerResponse.request
        ),
        {
          type: {
            type: Excel.CellValueType.string,
            basicValue: "ARBOR_NUMBER",
          },
          queryType: {
            type: Excel.CellValueType.string,
            basicValue: queryType,
          },
          query: {
            type: Excel.CellValueType.string,
            basicValue: query,
          },
          ticker: {
            type: Excel.CellValueType.string,
            basicValue: ticker,
          },
          reason: {
            type: Excel.CellValueType.string,
            basicValue: context,
          },
          knowledgeSpace: {
            type: Excel.CellValueType.string,
            basicValue: knowledgeSpace || "internet",
          },
          ...((deepResponse as ArborDeepSuccessResult).properties?.queriedAt?.basicValue && {
            queriedAt: {
              type: Excel.CellValueType.string,
              basicValue: (deepResponse as ArborDeepSuccessResult).properties.queriedAt?.basicValue || "",
            },
          }),
          ...((deepResponse as ArborDeepSuccessResult).properties?.privateFileFiltering?.elements && {
            privateFileFiltering: {
              type: Excel.CellValueType.array,
              elements: (deepResponse as ArborDeepSuccessResult).properties.privateFileFiltering.elements,
            },
          }),
          ...((deepResponse as ArborDeepSuccessResult).properties?.references?.elements && {
            references: {
              type: Excel.CellValueType.array,
              elements: (deepResponse as ArborDeepSuccessResult).properties.references.elements,
            },
          }),
          ...((deepResponse as ArborDeepSuccessResult).properties?.subqueries?.elements && {
            subqueries: {
              type: Excel.CellValueType.array,
              elements: (deepResponse as ArborDeepSuccessResult).properties.subqueries.elements,
            },
          }),
        }
      );
      console.log("ARBOR_NUMBER", ticker, query, errorEntity);
      if (!isSupported) {
        return errorEntity.text;
      }
      return errorEntity;
    }

    const numberAnswer = numberAnswerResponse.data.result;
    const entity: ArborNumberSuccessResult = {
      type: Excel.CellValueType.entity,
      text: `${numberAnswer.answer}`,
      provider: deepResponse.provider,
      properties: {
        ...(deepResponse as ArborDeepSuccessResult).properties,
        type: {
          type: Excel.CellValueType.string,
          basicValue: "ARBOR_NUMBER",
        },
        success: {
          type: Excel.CellValueType.boolean,
          basicValue: true,
        },
        queryType: {
          type: Excel.CellValueType.string,
          basicValue: queryType,
        },
        answer: {
          type: Excel.CellValueType.double,
          basicValue: numberAnswer.answer,
        },
        reason: {
          type: Excel.CellValueType.string,
          basicValue: context,
        },
        knowledgeSpace: {
          type: Excel.CellValueType.string,
          basicValue: knowledgeSpace || "internet",
        },
        ...((deepResponse as ArborDeepSuccessResult).properties?.privateFileFiltering?.elements && {
          privateFileFiltering: {
            type: Excel.CellValueType.array,
            elements: (deepResponse as ArborDeepSuccessResult).properties.privateFileFiltering.elements,
          },
        }),
        ...((deepResponse as ArborDeepSuccessResult).properties?.references?.elements && {
          references: {
            type: Excel.CellValueType.array,
            elements: (deepResponse as ArborDeepSuccessResult).properties.references.elements,
          },
        }),
        ...((deepResponse as ArborDeepSuccessResult).properties?.subqueries?.elements && {
          subqueries: {
            type: Excel.CellValueType.array,
            elements: (deepResponse as ArborDeepSuccessResult).properties.subqueries.elements,
          },
        }),
      },
      layouts: {
        compact: {
          icon: successCellIcon,
        },
      },
    };
    console.log("ARBOR_NUMBER", ticker, query, entity);
    if (!isSupported) {
      return entity.text;
    }
    return entity;
  } catch (error: any | AxiosError) {
    const errorEntity = returnErrorEntity<ArborNumberFailResult>(error, {
      type: {
        type: Excel.CellValueType.string,
        basicValue: "ARBOR_NUMBER",
      },
      queryType: {
        type: Excel.CellValueType.string,
        basicValue: queryType,
      },
      query: {
        type: Excel.CellValueType.string,
        basicValue: query,
      },
      ticker: {
        type: Excel.CellValueType.string,
        basicValue: ticker,
      },
      knowledgeSpace: {
        type: Excel.CellValueType.string,
        basicValue: knowledgeSpace || "internet",
      },
    });
    console.log("ARBOR_NUMBER", ticker, query, errorEntity);
    if (!isSupported) {
      return errorEntity.text;
    }
    return errorEntity;
  }
}

CustomFunctions.associate("ARBOR_NUMBER", answerNumber);